DROP TABLE IF EXISTS public.players CASCADE;

CREATE TABLE public.players (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  player_id INTEGER UNIQUE NOT NULL,
  name TEXT NOT NULL,
  team TEXT NOT NULL,
  role TEXT NOT NULL,
  base_price INTEGER NOT NULL,
  avatar_initials TEXT NOT NULL,
  country TEXT DEFAULT 'India',
  city TEXT DEFAULT 'Unknown',
  batting_style TEXT DEFAULT 'Right Handed Bat',
  bowling_style TEXT DEFAULT 'Right-arm medium',
  image_url TEXT,
  stats JSONB DEFAULT '{}'::jsonb
);

-- Enable RLS
ALTER TABLE public.players ENABLE ROW LEVEL SECURITY;

-- Create a policy to allow anyone to read players
DROP POLICY IF EXISTS "Allow public read access to players" ON public.players;
CREATE POLICY "Allow public read access to players" ON public.players FOR SELECT USING (true);

